; ------------------------------------------------------------------------
; RAM the intro used beyond the loaded image ($71000-$77FFF).
; Must stay contiguous with the image: LAB_68050 clears $6B500-$76000.
; ------------------------------------------------------------------------
BSS_71000:
	DS.B	$A00
BSS_71A00:
	DS.B	$149
BSS_71B49:
	DS.B	$B0F
BSS_72658:
	DS.B	$B22
